SELECT *, FIRST_VALUE(job_title) IGNORE NULLS OVER (PARTITION BY level, dept_id ORDER BY salary ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_job_title, SUM(salary) OVER (PARTITION BY dept_id ORDER BY salary ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary, SUM(salary) OVER (ORDER BY hire_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary_2 FROM employees WHERE full_name IS NOT NULL
